327→export default function ScannerIndex() {
328→    const [state, setState] = useState<ScannerState>('instructions');
329→    const [animal, setAnimal] = useState<AnimalResult | null>(null);
330→
331→    const handleResult = (a: AnimalResult) => {
332→        setAnimal(a);
333→        setState('result');
334→    };
335→
336→    const handleError = () => setState('error');
337→    const handlePermissionDenied = () => setState('permission_denied');
338→
339→    return (
340→        <AppLayout breadcrumbs={breadcrumbs}>
341→            <Head title="Escanear Crotal" />
342→            <div className="flex h-full flex-col">
343→                {state === 'instructions' && (
344→                    <ScanInstructions onStart={() => setState('camera')} onManual={() => setState('manual')} />
345→                )}
346→                {state === 'camera' && (
347→                    <div className="relative min-h-[500px] flex-1">
348→                        <CameraView onResult={handleResult} onError={() => { if (state === 'camera') handleError(); }} />
349→                    </div>
