357→                {state === 'manual' && <ManualInput onResult={handleResult} />}
358→                {state === 'permission_denied' && <PermissionDenied onManual={() => setState('manual')} />}
359→
360→                {(state === 'camera') && (
361→                    <div className="flex items-center justify-center border-t-2 border-black bg-white p-4">
362→                        <button onClick={() => setState('manual')} className="text-sm font-semibold text-[#757575]">
363→                            Introducir código manualmente
364→                        </button>
365→                    </div>
366→                )}
367→            </div>
368→        </AppLayout>
