 91→function CameraView({ onResult, onError }: { onResult: (animal: AnimalResult) => void; onError: () => void }) {
 92→    const videoRef = useRef<HTMLVideoElement>(null);
 93→    const canvasRef = useRef<HTMLCanvasElement>(null);
 94→    const streamRef = useRef<MediaStream | null>(null);
 95→    const [torch, setTorch] = useState(false);
 96→    const [hasTorch, setHasTorch] = useState(false);
 97→    const [statusText, setStatusText] = useState('Enfoca el crotal del animal');
 98→    const { recognizeFrame, isProcessing, terminate } = useCrotalOcr();
 99→    const scanningRef = useRef(true);
100→
101→    const startCamera = useCallback(async () => {
102→        try {
103→            const stream = await navigator.mediaDevices.getUserMedia({
104→                video: { facingMode: 'environment', width: { ideal: 1280 }, height: { ideal: 720 } },
105→            });
106→            streamRef.current = stream;
107→            if (videoRef.current) {
108→                videoRef.current.srcObject = stream;
109→            }
110→            const track = stream.getVideoTracks()[0];
111→            const caps = track.getCapabilities?.() as MediaTrackCapabilities & { torch?: boolean };
112→            if (caps?.torch) setHasTorch(true);
113→        } catch {
114→            onError();
115→        }
116→    }, [onError]);
117→
118→    useEffect(() => {
119→        startCamera();
120→
121→        return () => {
122→            scanningRef.current = false;
123→            streamRef.current?.getTracks().forEach((t) => t.stop());
124→            terminate();
125→        };
126→    }, [startCamera, terminate]);
127→
128→    const toggleTorch = async () => {
129→        const track = streamRef.current?.getVideoTracks()[0];
130→        if (track) {
131→            await track.applyConstraints({ advanced: [{ torch: !torch } as MediaTrackConstraintSet] });
132→            setTorch(!torch);
133→        }
134→    };
135→
136→    useEffect(() => {
137→        const startTime = Date.now();
138→        let intervalId: ReturnType<typeof setInterval>;
139→
140→        const runOcr = async () => {
141→            if (!scanningRef.current || !videoRef.current || !canvasRef.current) return;
142→
143→            if (Date.now() - startTime > SCAN_TIMEOUT_MS) {
144→                scanningRef.current = false;
145→                clearInterval(intervalId);
146→                onError();
147→
148→                return;
149→            }
150→
151→            setStatusText('Analizando...');
152→            const code = await recognizeFrame(videoRef.current, canvasRef.current);
153→
154→            if (!scanningRef.current) return;
155→
156→            if (code) {
157→                scanningRef.current = false;
158→                clearInterval(intervalId);
159→                setStatusText('Crotal detectado, buscando animal...');
160→
161→                try {
162→                    const res = await fetch(`/api/animals/by-crotal/${encodeURIComponent(code)}`);
163→                    if (res.ok) {
164→                        const animal = await res.json();
165→                        onResult(animal);
166→
167→                        return;
168→                    }
169→                } catch { /* fall through */ }
170→
171→                onError();
172→            } else {
173→                setStatusText('Enfoca el crotal del animal');
174→            }
175→        };
176→
177→        intervalId = setInterval(runOcr, SCAN_INTERVAL_MS);
178→
179→        return () => clearInterval(intervalId);
180→    }, [onError, onResult, recognizeFrame]);
